class Seat {
    private final int row;
    private final int number;

    Seat(int row, int number) {
        this.row = row;
        this.number = number;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Seat)) {
            return false;
        }
        Seat other = (Seat) o;
        return row == other.row && number == other.number;
    }

    @Override
    public int hashCode() {
        return 31 * row + number;
    }
}

