import java.util.*;

public class Main {
    static Map<String, Integer> tally(List<String> votes) {
        Map<String, Integer> counts = new HashMap<String, Integer>();
        for (String v : votes) {
            Integer old = counts.get(v);
            counts.put(v, old == null ? 1 : old + 1);
        }
        return counts;
    }

    static String winner(Map<String, Integer> counts) {
        String best = null;
        int bestCount = 0;
        for (Map.Entry<String, Integer> e : counts.entrySet()) {
            int c = e.getValue();
            if (best == null || c > bestCount
                    || (c == bestCount && e.getKey().compareTo(best) < 0)) {
                best = e.getKey();
                bestCount = c;
            }
        }
        return best;
    }
}

