import java.util.*;

public class Main {
    static long ways(int n) {
        return ways(n, new HashMap<Integer, Long>());
    }

    private static long ways(int n, Map<Integer, Long> memo) {
        if (n < 0) {
            return 0;
        }
        if (n == 0) {
            return 1;
        }
        Long known = memo.get(n);
        if (known != null) {
            return known;
        }
        long total = ways(n - 1, memo) + ways(n - 2, memo) + ways(n - 3, memo);
        memo.put(n, total);
        return total;
    }
}

