abstract class Staff {
    private final String name;

    Staff(String name) {
        this.name = name;
    }

    abstract int monthlyPay();

    String payslip() {
        return name + " earns " + monthlyPay();
    }
}

class Salaried extends Staff {
    private final int yearly;

    Salaried(String name, int yearly) {
        super(name);
        this.yearly = yearly;
    }

    @Override
    int monthlyPay() {
        return yearly / 12;
    }
}

class Hourly extends Staff {
    private final int rate;
    private final int hours;

    Hourly(String name, int rate, int hours) {
        super(name);
        this.rate = rate;
        this.hours = hours;
    }

    @Override
    int monthlyPay() {
        int normal = Math.min(hours, 160);
        int overtime = Math.max(0, hours - 160);
        return normal * rate + overtime * rate * 3 / 2;
    }
}

