import java.util.*;

public class Main {
    static <T extends Comparable<T>> T maxOf(List<T> items) {
        if (items.isEmpty()) {
            throw new IllegalArgumentException("empty list");
        }
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) {
                best = item;
            }
        }
        return best;
    }

    static <T extends Comparable<T>> int countAbove(List<T> items, T limit) {
        int count = 0;
        for (T item : items) {
            if (item.compareTo(limit) > 0) {
                count++;
            }
        }
        return count;
    }
}

