questions.model_code:
enum Stage {
    ORDERED(3), PACKED(2), SHIPPED(1), DELIVERED(0);

    private final int daysLeft;

    Stage(int daysLeft) {
        this.daysLeft = daysLeft;
    }

    int daysLeft() {
        return daysLeft;
    }

    boolean isFinal() {
        return this == DELIVERED;
    }

    Stage next() {
        switch (this) {
            case ORDERED:
                return PACKED;
            case PACKED:
                return SHIPPED;
            default:
                return DELIVERED;
        }
    }
}

public class Main {
    static Stage advance(Stage start, int steps) {
        Stage s = start;
        for (int i = 0; i < steps; i++) {
            s = s.next();
        }
        return s;
    }
}

