import java.util.*;

class Roster {
    private final List<String> names = new ArrayList<String>();

    void add(String name) {
        names.add(name);
    }

    int nameLength(int index) {
        return names.get(index).length();
    }

    int longest() {
        int best = 0;
        for (int i = 0; i < names.size(); i++) {
            best = Math.max(best, nameLength(i));
        }
        return best;
    }
}

public class Main {
    public static void main(String[] args) {
        Roster r = new Roster();
        r.add("Leon");
        r.add(null);
        try { System.out.println(r.longest()); } catch (NullPointerException e) { System.out.println(e.getClass().getName()); for (StackTraceElement s : e.getStackTrace()) { System.out.println(s.getClassName() + "." + s.getMethodName() + ":" + s.getLineNumber()); } }
